for kind in ['hydrostatic','continuity','power','water-volume','mixture','nozzle-speed']:
 for n in range(1,21):
  if kind=='hydrostatic':
   x=n; result=Decimal(1000)*Decimal('9.8')*x/1000;unit='kPa';subject=SUBJECTS[1];stem=f'밀도 1,000 kg/m³인 정지한 물의 자유표면 아래 {x} m에서 게이지압은? 중력가속도는 9.8 m/s², 자유표면은 대기압이다.';formula=f'p=ρgh=1000×9.8×{x}={result*1000} Pa={result} kPa';values=[x]
  elif kind=='continuity':
   x=n*2;result=Decimal(x)*3;unit='L/s';subject=SUBJECTS[1];stem=f'물이 단면적 {x*10} cm²인 관에서 평균 3 m/s로 흐른다. 체적유량은 몇 L/s인가?';formula=f'A={x*10}×10⁻⁴ m², Q=Av={x*10}×10⁻⁴×3={result/1000} m³/s={result} L/s';values=[x*10,3]
  elif kind=='power':
   x=n;result=Decimal('9.8')*x;unit='kW';subject=SUBJECTS[1];stem=f'밀도 1,000 kg/m³인 물을 유량 {x*10} L/s, 양정 100 m로 보내는 펌프의 수동력은? g=9.8 m/s²이며 효율을 반영하기 전 유효 수동력이다.';formula=f'Q={x*10}/1000 m³/s, P=ρgQH=1000×9.8×{x/100}×100={result*1000} W={result} kW';values=[x*10,100]
  elif kind=='water-volume':
   x=n*100;result=Decimal(x)*20/1000;unit='m³';subject=SUBJECTS[3];stem=f'일정 유량 {x} L/min으로 20분 동안 방수할 때 순수 방수량은? 누설과 여유량은 무시하며 법정 수원량을 묻는 문제가 아니다.';formula=f'V=Qt={x}×20={x*20} L={result} m³';values=[x,20]
  elif kind=='mixture':
   x=n*100;result=Decimal(x)*Decimal('0.03');unit='L';subject=SUBJECTS[3];stem=f'최종 포 수용액 {x} L를 체적비 3%로 혼합한다고 가정할 때 필요한 포 원액은? 체적 가산성을 가정하며 제품의 지정 혼합비나 법정 기준을 묻지 않는다.';formula=f'V원액=0.03×V수용액=0.03×{x}={result} L';values=[x,3]
  else:
   x=Decimal(n*n)/5;result=(2*Decimal(10)*x).sqrt();unit='m/s';subject=SUBJECTS[3];stem=f'대기 중으로 방수하는 이상적인 노즐의 속도수두가 {x} m일 때 유속은? g=10 m/s²로 가정하고 손실수두는 무시한다.';formula=f'v²/(2g)=h에서 v=√(2gh)=√(2×10×{x})={result} m/s';values=[float(x),10]
  def fmt(v):return format(v.normalize(),'f')
  choices=[f'{fmt(result*f)} {unit}' for f in [Decimal(1),Decimal(2),Decimal('0.5'),Decimal(3)]]
  add(subject,'기초 계산',stem,choices,f'주어진 조건을 SI 단위로 환산한다. {formula}. 따라서 답은 {fmt(result)} {unit}이다. 주어진 이상화 조건에서의 계산이며 실제 설비 선정 시 손실·안전 조건은 별도 검토한다.',kind,dict(kind=kind,values=values,result=float(result),unit=unit,precision=2))
